import type { Logger } from '@servicenow/sdk-build-core'
import winston from 'winston'
import chalk from 'chalk'

class CLILogger implements Logger {
    private readonly logger: winston.Logger

    public readonly info: Logger['info']
    public readonly debug: Logger['debug']
    public readonly warn: Logger['warn']
    public readonly error: Logger['error']

    constructor(private readonly level: LogLevel = 'info') {
        function printLogLevel(level: LogLevel) {
            if (['error', 'warn', 'debug'].includes(level)) {
                return ` ${level.toUpperCase()}:`
            }

            return ''
        }

        this.logger = winston.createLogger({
            level: this.level,
            format: winston.format.printf(({ level, message, stack }) => {
                const stacktrace = stack && this.logger.level === 'debug' ? `\n${stack}` : ''
                const logMessage = `[now-sdk]${printLogLevel(level as LogLevel)} ${message}${stacktrace}`

                switch (level) {
                    case 'error':
                        return chalk.red(logMessage)
                    case 'warn':
                        return chalk.yellow(logMessage)
                    default:
                        return logMessage
                }
            }),
            transports: [new winston.transports.Console()],
        })

        this.info = this.logger.info.bind(this.logger)
        this.warn = this.logger.warn.bind(this.logger)
        this.debug = this.logger.debug.bind(this.logger)
        this.error = this.logger.error.bind(this.logger)

        if (this.level !== 'debug' && process.env['LOG_LEVEL']) {
            this.level = process.env['LOG_LEVEL'] as LogLevel
            this.info(`Setting log level to ${this.level} from process.env.LOG_LEVEL`)
        }
    }

    public setLevel(level: LogLevel) {
        this.logger.level = level
    }
}

export type LogLevel = 'info' | 'debug' | 'warn' | 'error'

export const logger = new CLILogger()
